            <li key={ing.text} className="flex flex-wrap items-baseline gap-x-3">
              {ing.scaledQtyDisplay && <span className="font-semibold text-accent">{ing.scaledQtyDisplay}</span>}
              <span>{ing.text}</span>
              {ing.changed && <Badge tone="ai">AI-adapted</Badge>}
            </li>
          ))}
        </ul>

