@import "tailwindcss";

/* Mise design tokens. Warm kitchen palette, burnt-orange accent.
   App is light; cook mode is dark (wrap it in .theme-cook). */
:root {
  --bg: #faf6ef;
  --surface: #ffffff;
  --surface-2: #f2ebe0;
  --ink: #221d17;
  --muted: #6b6155;
  --line: #e4dacb;
  --accent: #b83a09;
  --accent-ink: #fff8f1;
  --accent-soft: #fbe6da;
  --warn: #8a5a00;
  --warn-soft: #fbf1cf;
  --danger: #a1123f;
  --danger-soft: #fce7ee;
  --ai: #5b4bb7;
  --ai-soft: #ece9fb;
}

.theme-cook {
  --bg: #13110e;
  --surface: #1d1a16;
  --surface-2: #2a2621;
  --ink: #f7f2ea;
  --muted: #b9ae9f;
  --line: #3a342d;
  --accent: #ff8a57;
  --accent-ink: #2a1206;
  --accent-soft: #3a2319;
  --warn: #f5b04c;
  --warn-soft: #3a2b14;
  --danger: #ff7a9a;
  --danger-soft: #3d1c28;
  --ai: #b3a8ff;
  --ai-soft: #2a2546;
  background: var(--bg);
  color: var(--ink);
}

@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-ink: var(--ink);
  --color-muted: var(--muted);
  --color-line: var(--line);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-accent-soft: var(--accent-soft);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-danger: var(--danger);
  --color-danger-soft: var(--danger-soft);
  --color-ai: var(--ai);
  --color-ai-soft: var(--ai-soft);
  --font-sans: var(--font-manrope);
  --font-display: var(--font-manrope);
}

body {
  background: var(--bg);
  color: var(--ink);
  font-weight: 500;
}

.font-display {
  font-weight: 800;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,

input.old_string:
  --ai: #5b4bb7;
