/* Mise design tokens. Warm kitchen palette, burnt-orange accent.
   App is light; cook mode is dark (wrap it in .theme-cook). */
:root {
  --bg: #faf6ef;
  --surface: #ffffff;
  --surface-2: #f2ebe0;
  --ink: #221d17;
  --muted: #6b6155;
  --line: #e4dacb;
  --accent: #b83a09;
  --accent-ink: #fff8f1;
  --accent-soft: #fbe6da;
  --warn: #8a5a00;
  --warn-soft: #fbf1cf;
  --danger: #a1123f;
  --danger-soft: #fce7ee;
  --ai: #5b4bb7;
  --ai-soft: #ece9fb;
  --success: #1f7a37;
  --success-soft: #e1f3e5;
}

.theme-cook {
  --bg: #13110e;
  --surface: #1d1a16;
  --surface-2: #2a2621;
  --ink: #f7f2ea;
  --muted: #b9ae9f;
  --line: #3a342d;
  --accent: #ff8a57;
  --accent-ink: #2a1206;
  --accent-soft: #3a2319;
  --warn: #f5b04c;
  --warn-soft: #3a2b14;
  --danger: #ff7a9a;
  --danger-soft: #3d1c28;
  --ai: #b3a8ff;
  --ai-soft: #2a2546;
  --success: #6cc08b;
  --success-soft: #1f3a28;
  background: var(--bg);
  color: var(--ink);
}

@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
