  background: var(--bg);
  color: var(--ink);
  font-weight: 500;
}

.font-display {
  font-weight: 800;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

dialog::backdrop {
  background: rgb(0 0 0 / 0.5);
}
